            dataToSend.services = Utils.obtainObjectsIds(oClientValues_248295.selectedServices);

            this.signin_fields.fetch({
                data: dataToSend,
                error: (function(){
                    that.showLoadDataError();
                })
            });
        },
        emptyFields: function() {
            if(typeof oClientValues_248295.clientData !== 'undefined' && typeof oClientValues_248295.clientData.attributes.login !== 'undefined') {
                this.$('#idIptBktSignInlogin').val(oClientValues_248295.clientData.attributes.login);
            }
            else {
                this.$('#idIptBktSignInlogin').val('');
            }
            this.$('#idIptBktSignInpassword').val('');
            this.$('#idIptBktSignInlogin').removeClass('clsDivBktDefaultInputError');
            this.$('#idIptBktSignInpassword').removeClass('clsDivBktDefaultInputError');
        },
        drawClientInputField: function(field){
            if(parseInt(field.show_widget) === 1 && parseInt(field.validate) === 1){
                var template = _.template($("#idTemSignInInputSelectOption").html(), {iOptionValue: field.input_text, sOptionText: field.field_text});
                this.$('#idSelBktSignInLoginType').append(template);
            }
        },
        drawEventInputField: function(field){
            if(parseInt(field.show_widget) === 1){

                var sFieldText = field.field_text;

                if(parseInt(field.obligatory) === 1){
                    sFieldText = '* ' + field.field_text;
                }

                var sValue = "";
                if(typeof oClientValues_248295.clientData !== 'undefined') {
                    sValue = oClientValues_248295.clientData.attributes[field.input_text];
                }

                var sInputTemplate = this.getFieldTemplate(field);                

                var template = _.template($("#"+sInputTemplate).html(), {attributes: field, sShowText: sFieldText, sValue: sValue});
                this.$('#idBktDefaultSignInEventFields').append(template);  

                this.checkAndDrawSelectOptions(field);

                if(typeof bkt_init_widget.fields !== 'undefined'){
                    if(typeof bkt_init_widget.fields[field.input_text] !== 'undefined'){
                        $('#idIptBktSignIn'+field.input_text).val(bkt_init_widget.fields[field.input_text]);
                    }
                }
            }
        },  
        checkAndDrawSelectOptions: function(field){
            if(parseInt(field.type) === this.field.iTypeDrop){
                var iSelectList = parseInt(field.custom_fields_select_lists_id);

                if(iSelectList > 0){
                    for(var i = 0 ; i < this.SelectOptions.length ; i++){
                        if(parseInt(this.SelectOptions[i].custom_fields_select_lists_id) === iSelectList){
                            var template = _.template($("#idTemSignInInputSelectOption").html(), {iOptionValue: this.SelectOptions[i].value, sOptionText: this.SelectOptions[i].option_text});       
                            this.$('#idIptBktSignIn'+field.input_text).append(template);   
                        }
                    }
                }
            }
        },
        getFieldTemplate: function(field){
            var sInputTemplate = 'idTemSignInInputFieldsText';

            if(parseInt(field.type) === this.field.iTypeCheckbox){
                sInputTemplate = 'idTemSignInInputFieldsCheckBox';
            }
            else if(parseInt(field.type) === this.field.iTypeDrop){
                sInputTemplate = 'idTemSignInInputFieldsDrop';                    
            }
            else if(parseInt(field.type) === this.field.iTypeDropAndText){
                sInputTemplate = 'idTemSignInInputFieldsDropAndText';                    
            }

            return sInputTemplate;
        },
        hideFieldError: function(event){
            var eventId = event.target.id;

            if(eventId.length > 0){
                var sName = this.$('#' + event.target.id).attr('name');

                if(this.$('#idDivBktFieldError' + sName).is(':visible')){
                    this.$('#' + event.target.id).removeClass('clsDivBktDefaultInputError');
                    this.$('#idDivBktFieldError' + sName).hide();                
                }
                else if(this.$('#' + event.target.id).is(':visible')){
                    this.$('#' + event.target.id).removeClass('clsDivBktDefaultInputError');
                }
            }
        },
        showLoadDataError: function(){
            $("#idFormSignInContainer").hide();

            $("#idBktDefaultSignInErrorContainer").show();
            $('.clsDivBktWidgetDefaultLoadingContainer').remove();
        },
        showLoading: function(p_iIdentifier){
            $('#idBktWidgetDefaultBodyContainer').prepend('<div class="clsDivBktWidgetDefaultLoadingContainer clsDivBktLoadingContainer'+ p_iIdentifier +'"><div class="clsDivBktWidgetDefaultLoading"></div></div>');
        },
        hideLoading: function(p_iIdentifier){
            $('.clsDivBktLoadingContainer' + p_iIdentifier).remove();
        },
        checkAndDrawVoucherInputField: function(field){
            if(field === true){
                var template = _.template($("#idTemSignInVoucherInputField").html(), {});
                $('#idBktDefaultSignInEventFields').append(template);           
            }
        }
    });    

    return SignInFieldsList;    
});

define(['jquery', 'underscore', 'backbone', 'widgets/default/views/breadcrumb', 'widgets/default/models/creditcard'],
function($, _, Backbone, BreadCrumb, CreditCard){
    var CreditCardCaptureStr = Backbone.View.extend({
        el: $("#idDivBktPaymentGatewayStripeContainer"),         
        events: {
           'click #idBktDefaultCCCStrSubmitButton': 'sendCreditCardDataV3',
           'click #idDivBktCCCStrWhatsThis': 'showWhatsThis',
           'click #idDivBktCCCStrCardClose': 'closeWhatsThis',
           'click #idDivBktCCCStrErrorClose': 'closeError'
        },
        initialize: function(){    
            $(this.el).off();
            this.publickey = this.$el.find("#idBktDefaultCCCStrKey").text();
            this.errorMessage = this.$el.find("#idDivBktCCCStrError").text();
            this.identifier = new Date().getTime();
        },
        show: function(){  

        }, 
        start: function(){
            this.emptyContainers();

            if(!$('#idStripeCreditCardContainer').hasClass('StripeElement')){
                var that = this;

                that.showLoading();

                require(['https://js.stripe.com/v3/'], function(Str){
                    oStripe = Stripe(that.publickey);
                    var elements = oStripe.elements();

                    var elementStyles = {
                        base: {
                            color: '#666666',
                            fontFamily: 'Arial,Helvetica,Verdana',
                            fontSize: '1em',
                            '::placeholder': {
                                color: '#B7ADAD',
                                fontSize: '1em',
                            },
                        },
                    };

                    cardNumber = elements.create('cardNumber', {
                        style: elementStyles,
                    });
                    cardNumber.mount('#idStripeCreditCardContainer');

                    cardExpiry = elements.create('cardExpiry', {
                        style: elementStyles,
                    });
                    cardExpiry.mount('#idStripeExpiryContainer');

                    cardCvc = elements.create('cardCvc', {
                        style: elementStyles,
                    });
                    cardCvc.mount('#idStripeCvcContainer');

                    cardCvc.on('ready', function(){
                        that.hideLoading();
                    });
//                    that.hideLoading();
                });  
            }
            else{
                $('#idDivBktStripeError').html('');

                cardNumber.clear();
                cardExpiry.clear();
                cardCvc.clear();
            }
        },
        emptyContainers: function(){
            var someFields = ['#idInpExpiryYear', '#idInpExpiryMonth', '#idInpCreditCard', '#idInpHolderName', '#idInpCvc'];

            for(var i = 0 ; i < someFields.length ; i++){
                this.$(someFields[i]).val("");
                this.$(someFields[i]).removeClass('clsDivBktDefaultInputError');                
            }

            this.$('#idDivBktCCCStrCardInfo').hide();
            this.$('#idDivBktCCCStrError').hide();
        },
        sendCreditCardData: function(){
            var that = this;

            this.oCreditCard = new CreditCard();

            var someIdsOfEmptyFields = this.oCreditCard.getEmptyFields();

            if(someIdsOfEmptyFields.length > 0){
                 for(var i = 0 ; i < someIdsOfEmptyFields.length ; i++){
                     $(someIdsOfEmptyFields[i]).addClass('clsDivBktDefaultInputError');
                 }

                 return;
            }

            this.showLoading();
            this.$el.find('.clsBktDefaultCCCStrErrorMessage').remove();           

            require(['https://js.stripe.com/v2/'], function(Str){
                Stripe.setPublishableKey(that.publickey);
                Stripe.card.createToken($('#idFrmBktCCCStr'), that.stripeResponseHandler.bind(that));
            });   
        },
        stripeResponseHandler: function(status, response){
            var $form = $('#idFrmBktCCCStr');

            if(response.error){
                this.reportError(response);        
                this.hideLoading();
            } 
            else{
                var token = response.id;

                $form.append($('<input type="hidden" id="idBktStripeToken" name="stripeToken" />').val(token));                

                var bktToken = oClientValues_248295.bktToken;
                var sLogin = (typeof oClientValues_248295.clientData.attributes.logintype !== 'undefined') ? oClientValues_248295.clientData.attributes.login : oClientValues_248295.clientData.attributes.email;

                this.oCreditCard.set({stripeToken: token, bankType: 'stripe', name: this.$el.find("#idInpHolderName").val(), email: sLogin, bktToken: bktToken});

                var that = this;

                this.listenTo(this.oCreditCard, "change", function(){
                    if(that.oCreditCard.attributes['payment_done'] === true) {                       
                        Backbone.history.navigate('summary', {trigger: true, replace: true});
                    }
                    else{
                        that.showLoadDataError();
                    }

                    this.hideLoading();
                });            

                this.oCreditCard.fetch({
                    data: this.oCreditCard.attributes,
                    error: (function(){
                        that.showLoadDataError();
                    })
                });
           }
        },
        reportError: function(response){
            this.showLoadDataError();

            return false;
        },
        showWhatsThis: function(){
            $('#idDivBktCCCStrCardInfo').show();
        },
        closeWhatsThis: function(){
            $('#idDivBktCCCStrCardInfo').hide();
        },
        closeError: function(){
            $("#idDivBktCCCStrError").hide();
        },
        showLoadDataError: function(){
//            $(".clsBktDefaultWindow").hide();  
            $(".clsDivBktWidgetDefaultLoadingContainer").remove();
            this.$el.show();
            $("#idDivBktCCCStrError").show();              
        },
        showLoading: function(){
           $('#idBktDefaultCCCStrContainer').prepend('<div class="clsDivBktWidgetDefaultLoadingContainer clsDivBktLoadingContainer'+ this.identifier +'"><div class="clsDivBktWidgetDefaultLoading"></div></div>');
        },
        hideLoading: function(){
            $('.clsDivBktLoadingContainer' + this.identifier).remove();
        },


        sendCreditCardDataV3: function(){
            var that = this;

            this.oCreditCard = new CreditCard();

            var someIdsOfEmptyFields = this.oCreditCard.getEmptyFields();

            if(someIdsOfEmptyFields.length > 0){
                 for(var i = 0 ; i < someIdsOfEmptyFields.length ; i++){
                     $(someIdsOfEmptyFields[i]).addClass('clsDivBktDefaultInputError');
                 }

                 return;
            }

            this.showLoading();
            this.$el.find('.clsBktDefaultCCCStrErrorMessage').remove();

            oStripe.createPaymentMethod('card', cardNumber).then(function(result){
                if(result.error){ // Show error in payment form
                    $('#idDivBktStripeError').html(result.error.message);
                    that.hideLoading();
                } 
                else{ // Send paymentMethod.id to server
                    that.sendPaymentMethodV3(result);
                }
            });              
        },        
        sendPaymentMethodV3: function(result){
            var that = this;

            var token = (typeof result.paymentMethod !== 'undefined') ? result.paymentMethod.id : result.paymentIntent.id;

            var bktToken = oClientValues_248295.bktToken;
            var sLogin = (typeof oClientValues_248295.clientData.attributes.logintype !== 'undefined') ? oClientValues_248295.clientData.attributes.login : oClientValues_248295.clientData.attributes.email;

            this.oCreditCard.set({stripeToken: token, bankType: 'stripe', name: this.$el.find("#idInpHolderName").val(), email: sLogin, bktToken: bktToken});

            this.listenTo(this.oCreditCard, "change", function(){
                if(that.oCreditCard.attributes['payment_done'] === true){
                    Backbone.history.navigate('summary', {trigger: true, replace: true});
                }
                else if(that.oCreditCard.attributes['requires_action'] === true){
                    that.handleCardActionV3(that.oCreditCard.attributes['payment_intent']);
                }
                else{
                    that.showLoadDataError();
                    this.hideLoading();
                }
            });            

            this.oCreditCard.fetch({
                data: this.oCreditCard.attributes,
                error: (function(){
                    that.showLoadDataError();
                })
            });          
        },
        handleCardActionV3: function(paymentIndent){
            var that = this;

            oStripe.handleCardAction(paymentIndent).then(function(result){
                if(result.error){
                    $('#idDivBktStripeError').html(result.error.message);
                    that.hideLoading();
                } 
                else{
                    that.sendPaymentMethodV3(result);
                }
            });            

        }   
    });

    return CreditCardCaptureStr;
});

