            var that = this;
            
            var data = $.extend(true, {}, bkt_init_widget);
            data.services = Utils.obtainObjectsIds(oClientValues_248295.selectedServices);
            data.agendas = Utils.obtainObjectsIds(oClientValues_248295.selectedAgendas);
            data.date = oClientValues_248295.selectedDate;
            data.time = oClientValues_248295.selectedTime;
            data.selectedPeople = oClientValues_248295.selectedPeople;
                
            if(typeof oClientValues_248295.bktToken !== "undefined"){
                data.bktToken = oClientValues_248295.bktToken;
            }
                
            _.each(this.client.attributes, function(value, key){
                data[key] = encodeURIComponent(value);
            });
            
            if(typeof oClientValues_248295.waitingListData !== "undefined"){
                data.waitinglist = oClientValues_248295.waitingListData;
            }            
            
            if(typeof oClientValues_248295.selectedExtras !== 'undefined'){
                data.extras = Utils.obtainExtrasIds(oClientValues_248295.selectedExtras);
            }            
																			
            if($('#idDivReCaptchaSignIn').length){
                data.gct = grecaptcha.getResponse(widgetBktReCaptchaSignIn);
            }					
			
            if($('#idDivHCaptchaSignIn').length){
                data.gct = hcaptcha.getResponse(widgetBktHCaptchaSignIn);
            }
            
            if($('#idDivCfCaptchaSignIn').length){
                data.gct = document.querySelector('#idDivBktSignInContainer input[name="cf-turnstile-response"]')?.value;
            }			
            
            this.client.url = Utils.get_server_url()+"signin/";
            
            if(typeof oClientValues_248295.signedInData !== "undefined" && typeof oClientValues_248295.signedInData.signedin !== "undefined"){
                this.client.url = Utils.get_server_url() + "signedin/";
            }            
            
            if($('#idDivReCaptchaSignIn.clsBktReCaptchaSignIn').length){
                grecaptcha.ready(function(){
                    grecaptcha.execute('6LdqftIZAAAAADcngqKaM97DRGXV47ca0Xk8spwH', {action: 'submit'}).then(function(token){
                        data.gctoken = token;
                        
                        that.client.fetch({
                            data: data,
                            error: (function(){
                                that.showLoadDataError();
                            })
                        });
                    });
                });
            }            
            else{
                this.client.fetch({
                    data: data,
                    error: (function(){
                        that.showLoadDataError();
                    })
                });  
            }  
        }
    });
    
    return SignInContainer;
});

define(['jquery', 'underscore', 'backbone', 'widgets/default/views/signup', 'widgets/utils', 'widgets/default/models/widgetconfiguration'],
function($, _, Backbone, SignUpContainer, Utils, WidgetConfiguration){
    var SignUpFirstAppointmentContainer = SignUpContainer.extend({
        initialize: function(){     
            this.widgetconfiguration = new WidgetConfiguration();
            this.checkFirstAppointment();

            SignUpFirstAppointmentContainer.__super__.initialize();
        },
        checkFirstAppointment: function(){
            if(typeof oClientValues_248295.widgetconfiguration.registration_type !== 'undefined' && parseInt(oClientValues_248295.widgetconfiguration.registration_type) === this.widgetconfiguration.iFirstAppointment){
                $('#idDivBktSignUpSubHeader').remove();
            }
        },
        handleSubmit: function(event){
            if(this.checkAndSetClientListenTo(event) === true){
                this.submit(event);
            }
        },
        submit: function(event){
            var that = this;

            var data = this.getDataToFetch(event);

            if(data === false){ return false; }

            this.client.url = Utils.get_server_url()+"signupfirstappointment/";

            if($('#idDivReCaptchaSignUp.clsBktReCaptchaSignUp').length){
                grecaptcha.ready(function(){
                    grecaptcha.execute('6LdqftIZAAAAADcngqKaM97DRGXV47ca0Xk8spwH', {action: 'submit'}).then(function(token){
                        data.gctoken = token;

                        that.client.fetch({
                            data: data,
                            error: (function(){
                                that.showLoadDataError();
                            })
                        });
                    });
                });
            }
            else{
                if($('#idDivReCaptcha').length && this.bReCaptcha === false){
                    this.bReCaptcha = true;

                    grecaptcha.reset();
                    grecaptcha.execute();
                }
                else{
                    if($('#idDivReCaptcha').length && this.bReCaptcha === true){
                        data.gct = grecaptcha.getResponse();
                        this.bReCaptcha = false;
                    }

                    this.client.fetch({
                        data: data,
                        error: (function(){
                            that.showLoadDataError();
                        })
                    });
                }
            }
        }


    });

    return SignUpFirstAppointmentContainer;
});

