                Backbone.history.navigate('waitinglistsummary', {trigger: true, replace: true});
                return false;
            } 

            return true;
        },
        arePaymentServices: function(){
            if(!this.oServices.arePaymentServices()){               
                Backbone.history.navigate('summary', {trigger: true, replace: true});
                return false;
            } 

