            if(this.iCountActivegateways > 1){
                $('#idDivBktPaymentsGatewaysContainer').show();

                if(this.bRedsysActive === true){
                    $("#idDivBktPaymentsGatewaysRedsys").show();
                }
                else if(this.bNiubizActive === true){
                    $("#idDivBktPaymentsGatewaysNiubiz").show();
