                if( (parseInt(field.obligatory) === 1) || (!bFirstAppointment && parseInt(field.validate) === 1) ){
                    sFieldText = '* ' + field.field_text;
                }

                var sValue = "";
                if(typeof oClientValues_248295.clientData !== 'undefined') {
