define(['jquery', 'underscore', 'backbone', 'widgets/default/models/client', 'widgets/utils', 'widgets/default/views/signin'],
function($, _, Backbone, Client, Utils , SignInContainer){
    var SignedInContainer = SignInContainer.extend({   
        render: function(){                
