                if(parseInt(this.services.models[0].attributes.multiservice) === 0){
                    return true;    
                }
                else if(parseInt(this.services.models[0].attributes.multiservice) !== 0 && parseInt(this.services.models[0].attributes.multiservice_number) === 1){
